<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { Archive, Lock, LockKeyholeOpen, Plus, RefreshCw, Trash2 } from 'lucide-vue-next'
import { selectPrimaryWorkspacePath, useAppStore } from '@/stores/appStore'
import { useZustandSelector } from '@/composables/useZustandSelector'
import { clearMemoriesByStatus, confirmMemoryCandidate, loadMemoryCount, loadMemoryPage, persistMemory, removeMemory, toggleMemoryLocked, updateMemoryStatus, type Memory } from '@/services/database/persistence'
import { contentHash, inferMemoryScope, normalizeMemoryScopeKey } from '@/services/memory/memoryPolicy'
import { toast } from '@/services/toast'
import { isTauri } from '@/hooks/useTauri'

const MEMORY_PAGE_SIZE = 20, CANDIDATE_PAGE_SIZE = 10
const { t } = useI18n()
const labels: Record<string, string> = { preference: t('memorySettings.categoryPreference'), project: t('memorySettings.categoryProject'), learning: t('memorySettings.categoryLearning'), profile: t('memorySettings.categoryProfile'), instruction: t('memorySettings.categoryInstruction'), context: t('memorySettings.categoryContext'), general: t('memorySettings.categoryGeneral') }
const sourceLabels: Record<string, string> = { user_explicit: t('memorySettings.sourceUserExplicit'), auto_extracted: t('memorySettings.sourceAutoExtracted'), manual_created: t('memorySettings.sourceManualCreated') }
const workspacePath = useZustandSelector(useAppStore, selectPrimaryWorkspacePath)
const memories = ref<Memory[]>([]), candidates = ref<Memory[]>([]), counts = ref({ active: 0, candidate: 0, archived: 0 }), activeTotal = ref(0), candidateTotal = ref(0), filter = ref('all'), scope = ref<'all' | 'global' | 'project'>('all'), activePage = ref(0), candidatePage = ref(0), refreshToken = ref(0), loading = ref(false), queryLoading = ref(false), showForm = ref(false), newContent = ref(''), newCategory = ref('preference')
const normalizedWorkspace = computed(() => normalizeMemoryScopeKey('project', workspacePath.value))
const scopeOptions = computed(() => scope.value === 'global' ? { scopeType: 'global' as const } : scope.value === 'project' ? { scopeType: 'project' as const, scopeKey: normalizedWorkspace.value, includeGlobalForProject: false } : {})
const categories = ['all', 'preference', 'project', 'learning', 'profile', 'instruction', 'context', 'general']
function date(value: number): string { return new Date(value).toLocaleDateString('zh-CN') }
function refresh(): void { refreshToken.value += 1 }
async function load(): Promise<void> { queryLoading.value = true; try { const [activeResult, candidateResult, activeCount, candidateCount, archivedCount] = await Promise.all([loadMemoryPage({ statuses: ['active'], category: filter.value === 'all' ? undefined : filter.value, ...scopeOptions.value, limit: MEMORY_PAGE_SIZE, offset: activePage.value * MEMORY_PAGE_SIZE }), loadMemoryPage({ statuses: ['candidate'], ...scopeOptions.value, limit: CANDIDATE_PAGE_SIZE, offset: candidatePage.value * CANDIDATE_PAGE_SIZE }), loadMemoryCount({ statuses: ['active'] }), loadMemoryCount({ statuses: ['candidate'] }), loadMemoryCount({ statuses: ['archived', 'superseded'] })]); const lastActive = Math.max(0, Math.ceil(activeResult.total / MEMORY_PAGE_SIZE) - 1), lastCandidate = Math.max(0, Math.ceil(candidateResult.total / CANDIDATE_PAGE_SIZE) - 1); if (activePage.value > lastActive) { activePage.value = lastActive; return }; if (candidatePage.value > lastCandidate) { candidatePage.value = lastCandidate; return }; memories.value = activeResult.memories; candidates.value = candidateResult.memories; activeTotal.value = activeResult.total; candidateTotal.value = candidateResult.total; counts.value = { active: activeCount, candidate: candidateCount, archived: archivedCount } } catch (error) { toast.error(error instanceof Error ? error.message : t('memorySettings.loadFailed')) } finally { queryLoading.value = false } }
async function run(action: () => Promise<void>): Promise<void> { loading.value = true; try { await action(); refresh() } catch (error) { toast.error(error instanceof Error ? error.message : t('memorySettings.operationFailed')) } finally { loading.value = false } }
async function add(): Promise<void> { const content = newContent.value.trim(); if (!content) return; await run(async () => { await persistMemory({ id: `mem-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, content, category: newCategory.value, source: 'manual_created', locked: false, status: 'active', ...inferMemoryScope(newCategory.value, workspacePath.value), factValue: content, confidence: 1, evidence: content, contentHash: contentHash(content), createdAt: Date.now(), updatedAt: Date.now() }); newContent.value = ''; newCategory.value = 'preference'; showForm.value = false; activePage.value = 0; toast.success(t('memorySettings.added')) }) }
async function confirmCandidate(id: string): Promise<void> { await run(async () => { const candidate = candidates.value.find((item) => item.id === id); const confirmed = await confirmMemoryCandidate(id); if (!confirmed) { toast.error(t('memorySettings.confirmFailed')); return }; if (candidate) { filter.value = candidate.category || 'all'; activePage.value = 0; candidatePage.value = 0 }; toast.success(t('memorySettings.confirmed')) }) }
async function ignoreCandidate(id: string): Promise<void> { await run(async () => { await updateMemoryStatus(id, 'ignored'); toast.success(t('memorySettings.ignored')) }) }
async function archiveMemory(id: string): Promise<void> { await run(async () => { await updateMemoryStatus(id, 'archived'); toast.success(t('memorySettings.archived')) }) }
async function deleteMemory(id: string): Promise<void> { if (!window.confirm(t('memorySettings.deleteConfirm'))) return; await run(async () => { await removeMemory(id); toast.success(t('memorySettings.deleted')) }) }
function setScope(value: 'all' | 'global' | 'project'): void { scope.value = value; activePage.value = 0; candidatePage.value = 0 }
function setFilter(value: string): void { filter.value = value; activePage.value = 0 }
watch([filter, scope, activePage, candidatePage, refreshToken], () => void load(), { immediate: true })
onBeforeUnmount(() => {})
</script>

<template>
  <section class="gm-vue-memory"><h3>{{ t('memorySettings.title') }}</h3><p v-if="!isTauri()" class="gm-vue-settings-notice">{{ t('memorySettings.browserUnavailable') }}</p><header><span>{{ t('memorySettings.summary', { active: counts.active, candidate: counts.candidate, archived: counts.archived }) }}</span><div><button type="button" :disabled="queryLoading" @click="refresh"><RefreshCw :size="14" />{{ t('memorySettings.refresh') }}</button><button type="button" class="gm-vue-settings-primary" @click="showForm = !showForm"><Plus :size="14" />{{ showForm ? t('memorySettings.cancel') : t('memorySettings.add') }}</button></div></header><section v-if="showForm" class="gm-vue-memory-form"><textarea v-model="newContent" :placeholder="t('memorySettings.placeholder')" /><footer><select v-model="newCategory"><option v-for="category in categories.filter((item) => item !== 'all' && item !== 'context' && item !== 'general')" :key="category" :value="category">{{ labels[category] }}</option></select><button type="button" class="gm-vue-settings-primary" :disabled="!newContent.trim() || loading" @click="add">{{ t('memorySettings.save') }}</button></footer></section><section v-if="candidateTotal" class="gm-vue-memory-candidates"><h4>{{ t('memorySettings.candidates') }}</h4><p>{{ t('memorySettings.candidatesHint') }}</p><article v-for="memory in candidates" :key="memory.id"><div><span>{{ labels[memory.category] || memory.category }}</span><em>{{ t('memorySettings.pending') }}</em><time>{{ date(memory.updatedAt) }}</time><p>{{ memory.content }}</p><small v-if="memory.supersedesId">{{ t('memorySettings.willReplace', { content: memories.find((item) => item.id === memory.supersedesId)?.content || t('memorySettings.existingMemory') }) }}</small></div><footer><button type="button" class="gm-vue-settings-primary" :disabled="loading" @click="confirmCandidate(memory.id)">{{ t('memorySettings.confirmSave') }}</button><button type="button" class="gm-vue-settings-danger" :disabled="loading" @click="ignoreCandidate(memory.id)">{{ t('memorySettings.ignore') }}</button></footer></article><div v-if="candidateTotal > CANDIDATE_PAGE_SIZE" class="gm-vue-memory-pagination"><button type="button" :disabled="candidatePage === 0 || queryLoading" @click="candidatePage--">{{ t('memorySettings.previous') }}</button><span>{{ t('memorySettings.candidatePage', { page: candidatePage + 1, pages: Math.ceil(candidateTotal / CANDIDATE_PAGE_SIZE) }) }}</span><button type="button" :disabled="(candidatePage + 1) * CANDIDATE_PAGE_SIZE >= candidateTotal || queryLoading" @click="candidatePage++">{{ t('memorySettings.next') }}</button></div></section><section class="gm-vue-memory-filter"><b>{{ t('memorySettings.scope') }}</b><div><button v-for="item in ['all', 'global', 'project'] as const" :key="item" type="button" :disabled="item === 'project' && !workspacePath" :data-active="scope === item" @click="setScope(item)">{{ item === 'all' ? t('memorySettings.allScopes') : item === 'global' ? t('memorySettings.global') : t('memorySettings.currentProject') }}</button></div><b>{{ t('memorySettings.type') }}</b><div><button v-for="item in categories" :key="item" type="button" :data-active="filter === item" @click="setFilter(item)">{{ item === 'all' ? t('memorySettings.allTypes') : labels[item] || item }}</button></div></section><p v-if="queryLoading" class="gm-vue-memory-loading">{{ t('memorySettings.loading') }}</p><p v-else-if="!memories.length" class="gm-vue-memory-loading">{{ counts.active === 0 ? t('memorySettings.empty') : t('memorySettings.noMemoriesInCategory') }}</p><article v-for="memory in memories" :key="memory.id" class="gm-vue-memory-row"><div><header><span>{{ labels[memory.category] || memory.category }}</span><span>{{ sourceLabels[memory.source] || memory.source }}</span><span>{{ memory.scopeType === 'project' ? t('memorySettings.currentProject') : t('memorySettings.global') }}</span><em v-if="memory.locked">{{ t('memorySettings.locked') }}</em><time>{{ date(memory.updatedAt) }}</time></header><p>{{ memory.content }}</p><small v-if="memory.subject && memory.factKey">{{ t('memorySettings.fact', { subject: memory.subject, factKey: memory.factKey, value: memory.factValue || memory.content }) }}</small><small v-if="memory.evidence && memory.evidence !== memory.content">{{ t('memorySettings.evidence', { evidence: memory.evidence }) }}</small></div><footer><button type="button" :title="memory.locked ? t('memorySettings.unlock') : t('memorySettings.lock')" :disabled="loading" @click="run(() => toggleMemoryLocked(memory.id, !memory.locked))"><LockKeyholeOpen v-if="memory.locked" :size="14" /><Lock v-else :size="14" /></button><button type="button" :title="t('memorySettings.archive')" :disabled="loading" @click="archiveMemory(memory.id)"><Archive :size="14" /></button><button type="button" :title="t('memorySettings.delete')" class="gm-vue-settings-danger" :disabled="loading" @click="deleteMemory(memory.id)"><Trash2 :size="14" /></button></footer></article><div v-if="activeTotal > MEMORY_PAGE_SIZE" class="gm-vue-memory-pagination"><button type="button" :disabled="activePage === 0 || queryLoading" @click="activePage--">{{ t('memorySettings.previous') }}</button><span>{{ t('memorySettings.page', { page: activePage + 1, pages: Math.ceil(activeTotal / MEMORY_PAGE_SIZE) }) }}</span><button type="button" :disabled="(activePage + 1) * MEMORY_PAGE_SIZE >= activeTotal || queryLoading" @click="activePage++">{{ t('memorySettings.next') }}</button></div></section>
</template>

<style scoped>
.gm-vue-memory { display: grid; gap: 12px; padding-bottom: 18px; }.gm-vue-memory h3,.gm-vue-memory h4 { margin: 0; color: var(--gm-text-tertiary); font-size: var(--gm-text-xs); text-transform: uppercase; }.gm-vue-memory > header,.gm-vue-memory > header > div,.gm-vue-memory-form footer,.gm-vue-memory-candidates article,.gm-vue-memory-row,.gm-vue-memory-row > div > header,.gm-vue-memory-row footer,.gm-vue-memory-pagination { display: flex; align-items: center; justify-content: space-between; gap: 8px; }.gm-vue-memory > header { color: var(--gm-text-secondary); font-size: var(--gm-text-xs); }.gm-vue-memory button { display: inline-flex; padding: 6px 8px; align-items: center; gap: 4px; color: var(--gm-text-secondary); border: 1px solid var(--gm-border); border-radius: var(--gm-radius-sm); background: var(--gm-surface); font-size: var(--gm-text-xs); }.gm-vue-memory-form,.gm-vue-memory-filter,.gm-vue-memory-candidates,.gm-vue-memory-row { padding: 11px; border: 1px solid var(--gm-border); border-radius: var(--gm-radius-md); background: var(--gm-surface-elevated); }.gm-vue-memory-form textarea { width: 100%; min-height: 70px; box-sizing: border-box; padding: 8px; color: var(--gm-text); border: 1px solid var(--gm-border); border-radius: var(--gm-radius-sm); background: var(--gm-surface); font: inherit; resize: vertical; }.gm-vue-memory-form footer { margin-top: 8px; }.gm-vue-memory-form select { padding: 6px; color: var(--gm-text); border: 1px solid var(--gm-border); border-radius: var(--gm-radius-sm); background: var(--gm-surface); }.gm-vue-memory-candidates { display: grid; gap: 8px; }.gm-vue-memory-candidates > p { margin: -4px 0 2px; color: var(--gm-text-secondary); font-size: var(--gm-text-xs); }.gm-vue-memory-candidates article,.gm-vue-memory-row { align-items: start; }.gm-vue-memory-candidates article > div,.gm-vue-memory-row > div { min-width: 0; flex: 1; }.gm-vue-memory-candidates span,.gm-vue-memory-row span,.gm-vue-memory-row em { display: inline-block; margin-right: 5px; padding: 2px 4px; border-radius: var(--gm-radius-sm); color: var(--gm-text-secondary); background: var(--gm-surface); font-size: 10px; font-style: normal; }.gm-vue-memory-candidates em { color: var(--gm-warning); }.gm-vue-memory-candidates time,.gm-vue-memory-row time { color: var(--gm-text-tertiary); font-size: 10px; }.gm-vue-memory-candidates p,.gm-vue-memory-row p { margin: 7px 0 0; color: var(--gm-text); white-space: pre-wrap; overflow-wrap: anywhere; font-size: var(--gm-text-sm); }.gm-vue-memory-candidates small,.gm-vue-memory-row small { display: block; margin-top: 4px; color: var(--gm-text-tertiary); font-size: var(--gm-text-xs); }.gm-vue-memory-filter { display: grid; gap: 7px; }.gm-vue-memory-filter b { color: var(--gm-text-secondary); font-size: var(--gm-text-xs); }.gm-vue-memory-filter div { display: flex; flex-wrap: wrap; gap: 5px; }.gm-vue-memory-filter button[data-active='true'] { color: var(--gm-primary); border-color: var(--gm-primary); background: color-mix(in srgb, var(--gm-primary) 10%, transparent); }.gm-vue-memory-loading { padding: 24px; color: var(--gm-text-tertiary); text-align: center; font-size: var(--gm-text-sm); }.gm-vue-memory-row > div > header { justify-content: start; flex-wrap: wrap; }.gm-vue-memory-row footer { flex: 0 0 auto; }.gm-vue-memory-row footer button { display: grid; padding: 5px; place-items: center; }.gm-vue-memory-pagination { justify-content: end; color: var(--gm-text-tertiary); font-size: var(--gm-text-xs); } @media (max-width: 650px) { .gm-vue-memory > header { align-items: start; flex-direction: column; }.gm-vue-memory-candidates article,.gm-vue-memory-row { flex-direction: column; }.gm-vue-memory-row footer { align-self: end; } }
</style>
